import{connect}from"puppeteer-core/lib/esm/puppeteer/puppeteer-core-browser.js";window.onConnectClick=async()=>{const e=document.getElementById("chrome-mobile-es-419")||document.getElementById("ws"),t=e?e.value:"",o=document.getElementById("output");if(!t)return console.error("No WebSocket URL provided"),void(o&&(o.textContent="Error: No WebSocket URL provided"));try{const e=await connect({browserWSEndpoint:t}),n=await e.newPage();await n.goto("https://example.com");const r=await n.title();console.log("Page title:",r),o&&(o.textContent=`Connected! Title: ${r}`),await e.disconnect()}catch(e){console.error("Connection failed:",e),o&&(o.textContent=`Error: ${e.message}`)}};